-- pure lua memory lib
--
-- CC-targeted rewrite. Two departures from stock wasm2lua:
--
-- 1. No _fp_map. Stock keeps a side table marking which cells hold floats so
--    float access avoids a bit-pattern conversion -- but that costs a hash
--    lookup and a branch on EVERY integer read and write. This module has ~31
--    float memory ops against ~4600 integer ones, so the trade is inverted:
--    floats are stored as bit patterns and the integer path stays flat.
-- 2. Internal bit work calls bit32 directly rather than going through the
--    LuaJIT-compatible `bit` shim, whose wrappers add a closure call and a sign
--    fixup that these functions don't need. Cell/byte splitting uses plain
--    arithmetic, which is a VM instruction rather than a C call.
--
-- Cells hold SIGNED 32-bit values, normalised on write.

local b32 = bit32
local b_band   = b32 and b32.band   or bit.band
local b_bor    = b32 and b32.bor    or bit.bor
local b_lshift = b32 and b32.lshift or bit.lshift
local b_rshift = b32 and b32.rshift or bit.rshift
local m_floor = math.floor
-- 256^byte_loc, for splitting a cell arithmetically instead of via bit32 calls
local pow8 = {[0]=1, 256, 65536, 16777216}

local function __MEM_OOM__(mem,loc)
    local signed = loc
    if type(loc) == 'number' and loc >= 2147483648 then signed = loc - 4294967296 end
    error(('out of memory access: loc=%s (as signed: %s) len=%s'):format(
        tostring(loc), tostring(signed), tostring(mem._len)), 0)
end

local function __MEMORY_GROW__(mem,pages)
    local old_pages = mem._page_count
    local new_pages = old_pages + pages

    -- check if new size exceeds the size limit
    if new_pages > mem._max_pages then
        return -1
    end

    -- 16k cells = 64kb = 1 page
    local cell_start = old_pages * 16 * 1024
    local cell_end = new_pages * 16 * 1024 - 1

    for i = cell_start, cell_end do 
        mem.data[i] = 0
    end

    mem._len = new_pages * 64 * 1024
    mem._page_count = new_pages
    return old_pages
end

local function __MEMORY_READ_8__(mem,loc)
    if (loc < 0) or (loc >= mem._len) then __MEM_OOM__(mem,loc) end
    local byte_loc = loc % 4
    local v = mem.data[(loc - byte_loc) / 4]
    if v < 0 then v = v + 4294967296 end
    return m_floor(v / pow8[byte_loc]) % 256
end

local function __MEMORY_READ_16__(mem,loc)
    if (loc < 0) or (loc >= (mem._len - 1)) then __MEM_OOM__(mem,loc) end
    local byte_loc = loc % 4
    if byte_loc ~= 3 then
        -- both bytes live in one cell
        return b_band(b_rshift(mem.data[(loc - byte_loc) / 4], byte_loc * 8), 65535)
    end
    return b_bor(
        __MEMORY_READ_8__(mem,loc),
        b_lshift(__MEMORY_READ_8__(mem,loc + 1),8)
    )
end

local function __MEMORY_READ_32__(mem,loc)
    if (loc < 0) or (loc >= (mem._len - 3)) then __MEM_OOM__(mem,loc) end
    local byte_loc = loc % 4
    if byte_loc == 0 then
        return mem.data[loc / 4]
    end
    local v = b_bor(
        __MEMORY_READ_8__(mem,loc),
        b_lshift(__MEMORY_READ_8__(mem,loc + 1),8),
        b_lshift(__MEMORY_READ_8__(mem,loc + 2),16),
        b_lshift(__MEMORY_READ_8__(mem,loc + 3),24)
    )
    if v >= 2147483648 then return v - 4294967296 end
    return v
end

local mask_table = {0xFFFF00FF,0xFF00FFFF,0x00FFFFFF}
mask_table[0] = 0xFFFFFF00
local function __MEMORY_WRITE_8__(mem,loc,val)
    if (loc < 0) or (loc >= mem._len) then __MEM_OOM__(mem,loc) end
    local byte_loc = loc % 4
    local cell_loc = (loc - byte_loc) / 4
    local p = pow8[byte_loc]
    local old = mem.data[cell_loc]
    if old < 0 then old = old + 4294967296 end
    -- replace one byte by arithmetic: subtract the old byte, add the new one
    local v = old + ((val % 256) - m_floor(old / p) % 256) * p
    if v >= 2147483648 then v = v - 4294967296 end
    mem.data[cell_loc] = v
end

local function __MEMORY_WRITE_16__(mem,loc,val)
    if (loc < 0) or (loc >= (mem._len - 1)) then __MEM_OOM__(mem,loc) end
    __MEMORY_WRITE_8__(mem,loc,     val)
    __MEMORY_WRITE_8__(mem,loc + 1, b_rshift(b_band(val,65535),8))
end

local function __MEMORY_WRITE_32__(mem,loc,val)
    if (loc < 0) or (loc >= (mem._len - 3)) then __MEM_OOM__(mem,loc) end
    if val == nil then error("NIL VALUE in write32 at loc=" .. tostring(loc), 0) end
    if loc % 4 == 0 then
        -- aligned write, fast path. Normalise here so reads never have to.
        if val >= 2147483648 or val < -2147483648 then
            val = b_band(val,0xFFFFFFFF)
            if val >= 2147483648 then val = val - 4294967296 end
        end
        mem.data[loc / 4] = val
    else
        __MEMORY_WRITE_8__(mem,loc,     val)
        __MEMORY_WRITE_8__(mem,loc + 1, b_rshift(val,8))
        __MEMORY_WRITE_8__(mem,loc + 2, b_rshift(val,16))
        __MEMORY_WRITE_8__(mem,loc + 3, b_rshift(val,24))
    end
end

-- Floats are stored as their bit patterns; see the header note.
local function __MEMORY_READ_32F__(mem,loc)
    return UInt32ToFloat(__MEMORY_READ_32__(mem,loc))
end

local function __MEMORY_READ_64F__(mem,loc)
    return UInt32sToDouble(__MEMORY_READ_32__(mem,loc),__MEMORY_READ_32__(mem,loc + 4))
end

local function __MEMORY_WRITE_32F__(mem,loc,val)
    __MEMORY_WRITE_32__(mem,loc,FloatToUInt32(val))
end

local function __MEMORY_WRITE_64F__(mem,loc,val)
    local low,high = DoubleToUInt32s(val)
    __MEMORY_WRITE_32__(mem,loc,low)
    __MEMORY_WRITE_32__(mem,loc + 4,high)
end

local function __MEMORY_INIT__(mem,loc,data)
    for i = 1, #data do -- TODO RE-OPTIMIZE
        __MEMORY_WRITE_8__(mem, loc + i-1, data:byte(i))
    end
end

-- Bulk memory operations (wasm bulk-memory proposal).
-- Operands arrive as signed 32 bit values; normalize them to unsigned.
local function __BULK_U32__(x)
    if x < 0 then return x + 4294967296 end
    return x
end

local function __MEMORY_COPY__(mem,dst,src,len)
    dst = __BULK_U32__(dst)
    src = __BULK_U32__(src)
    len = __BULK_U32__(len)
    if len == 0 or dst == src then return end
    if (dst + len) > mem._len or (src + len) > mem._len then __MEM_OOM__(mem,dst) end

    local data = mem.data
    local aligned = (dst % 4 == 0) and (src % 4 == 0)
    local words = (len - len % 4) / 4

    if dst < src then
        -- non-overlapping in the forward direction: copy low to high
        if aligned then
            local dcell, scell = dst / 4, src / 4
            for i = 0, words - 1 do
                data[dcell + i] = data[scell + i]
            end
            for i = words * 4, len - 1 do
                __MEMORY_WRITE_8__(mem, dst + i, __MEMORY_READ_8__(mem, src + i))
            end
        else
            for i = 0, len - 1 do
                __MEMORY_WRITE_8__(mem, dst + i, __MEMORY_READ_8__(mem, src + i))
            end
        end
    else
        -- regions may overlap with dst above src: copy high to low
        if aligned then
            for i = len - 1, words * 4, -1 do
                __MEMORY_WRITE_8__(mem, dst + i, __MEMORY_READ_8__(mem, src + i))
            end
            local dcell, scell = dst / 4, src / 4
            for i = words - 1, 0, -1 do
                data[dcell + i] = data[scell + i]
            end
        else
            for i = len - 1, 0, -1 do
                __MEMORY_WRITE_8__(mem, dst + i, __MEMORY_READ_8__(mem, src + i))
            end
        end
    end
end

local function __MEMORY_FILL__(mem,dst,val,len)
    dst = __BULK_U32__(dst)
    len = __BULK_U32__(len)
    if len == 0 then return end
    if (dst + len) > mem._len then __MEM_OOM__(mem,dst) end
    val = b_band(val,255)

    local i = 0
    while (i < len) and ((dst + i) % 4 ~= 0) do
        __MEMORY_WRITE_8__(mem, dst + i, val)
        i = i + 1
    end

    local word = b_bor(val,b_lshift(val,8),b_lshift(val,16),b_lshift(val,24))
    if word >= 2147483648 then word = word - 4294967296 end
    local data = mem.data
    while (i + 4) <= len do
        data[(dst + i) / 4] = word
        i = i + 4
    end

    while i < len do
        __MEMORY_WRITE_8__(mem, dst + i, val)
        i = i + 1
    end
end

local function __MEMORY_ALLOC__(pages, max_pages)
    local mem = {}
    mem.data = {}
    mem._page_count = pages
    mem._len = pages * 64 * 1024
    mem._max_pages = max_pages or 1024

    local cellLength = pages * 16 * 1024 -- 16k cells = 64kb = 1 page
    for i=0,cellLength - 1 do mem.data[i] = 0 end

    mem.write8 = __MEMORY_WRITE_8__
    mem.write16 = __MEMORY_WRITE_16__
    mem.write32 = __MEMORY_WRITE_32__

    mem.read8 = __MEMORY_READ_8__
    mem.read16 = __MEMORY_READ_16__
    mem.read32 = __MEMORY_READ_32__

    __SETJMP_STATES__[mem] = {}

    return mem
end
